import re, json
from pathlib import Path

manifest='/mnt/data/LSF/baseline_results/financebench/agentic_codex_qa_gpt54mini_all/single_cluster/all_docs/logs/all_docs.manifest.json'
obj=json.load(open(manifest))

num_re = re.compile(r'\\(?\\"'$?'"\\d[\\d,]*(?:\\.\\d+)?\\)?')
phone_re = re.compile(r'\\(?\\d{3}\\)?[\\s.-]?\\d{3}[\\s.-]?\\d{4}')
zip_re = re.compile(r'\\b\\d{5}(?:-\\d{4})?\\b')


def clean(s):
    return re.sub(r'\\s+', ' ', s).strip()

def is_label_like(line):
    s = clean(line)
    if not s:
        return False
    if s in {'"'$'"', '—', '-', '•'}:
        return False
    if num_re.fullmatch(s):
        return False
    if phone_re.fullmatch(s):
        return False
    # reject common purely numeric/date lines
    if re.fullmatch(r'[\\d,\\.\\-()/ ]+', s):
        return False
    # likely label if it has letters
    return bool(re.search(r'[A-Za-z]', s))


def first_numeric_after(lines, idx, max_look=8):
    seen_label=False
    for j in range(idx+1, min(len(lines), idx+1+max_look)):
        s=clean(lines[j])
        if not s:
            continue
        m=num_re.search(s)
        if m:
            return m.group(0).replace('"'$'"','')
        if is_label_like(s):
            # if a new label appears before numeric, likely not this row
            return None
    return None


def find_best_heading(lines, patterns, score_labels=None):
    best=(-1,-1)
    best_i=None
    low=[l.lower() for l in lines]
    for i,l in enumerate(low):
        if any(p in l for p in patterns):
            # heading-like if short or title-ish
            score=0
            if score_labels:
                window='\\n'.join(low[i:i+80])
                for lab in score_labels:
                    if lab in window:
                        score += 1
                # bonus for numeric density
                score += sum(1 for x in low[i:i+40] if num_re.search(x))
            else:
                score = sum(1 for x in low[i:i+40] if num_re.search(x))
            if (score, i) > best:
                best=(score,i)
                best_i=i
    return best_i


def extract_row_value(lines, start, label_patterns, max_look=120):
    low=[l.lower() for l in lines]
    for i in range(start, min(len(lines), start+max_look)):
        s=clean(low[i])
        if not s:
            continue
        for pat in label_patterns:
            if pat in s:
                # ensure the label row is not just a section heading with other label rows before numeric
                val=first_numeric_after(lines, i)
                if val is not None:
                    return val, i
                break
    return None, None


def extract_cover(lines):
    low=[l.lower() for l in lines]
    def prev_nonempty(idx, n=1):
        cnt=0
        for j in range(idx-1, -1, -1):
            s=clean(lines[j])
            if not s:
                continue
            cnt += 1
            if cnt==n:
                return s, j
        return None, None
    def preceding_block(idx, max_lines=3):
        out=[]
        for j in range(idx-1, -1, -1):
            s=clean(lines[j])
            if not s:
                if out:
                    break
                continue
            # stop if we hit obvious non-address metadata after collecting something
            if len(out)>=max_lines:
                break
            out.append(s)
        return list(reversed(out))

    # exact name
    exact = None
    for i,l in enumerate(low):
        if 'exact name of registrant' in l:
            exact,_ = prev_nonempty(i)
            break

    state = None; ein = None
    for i,l in enumerate(low):
        if 'state or other jurisdiction' in l:
            state,_ = prev_nonempty(i)
            break
    for i,l in enumerate(low):
        if 'irs employer' in l and 'identification no' in l:
            ein,_ = prev_nonempty(i)
            break

    phone = None
    for i,l in enumerate(lines):
        if 'telephone number' in l.lower():
            phone = phone_re.search(clean(lines[i-1] if i>0 else ''))
            if phone:
                phone = phone.group(0)
            break

    addr = None
    for i,l in enumerate(low):
        if 'address of principal executive offices' in l or 'address and telephone number' in l:
            block=preceding_block(i, 3)
            # drop company name if accidentally captured
            addr = ', '.join(block)
            break

    shares = None
    for pat in [r'([\\d,]+) shares of common stock were issued and outstanding',
                r'as of ["'^'"\\n]*,?\\s*([\\d,]+) shares of common stock were outstanding',
                r'number of shares of common stock outstanding as of ["'^'"\\n]*\\s*([\\d,]+)',
                r'([\\d,]+) shares of common stock outstanding']:
        m=re.search(pat, '\\n'.join(lines), flags=re.I)
        if m:
            shares=m.group(1)
            break

    # symbol/exchange
    symbol=None; exchange=None
    for i,l in enumerate(low):
        if 'trading symbol' in l:
            for j in range(i+1, min(len(lines), i+20)):
                s=clean(lines[j])
                if not s or 'securities registered' in s.lower():
                    continue
                # symbol line usually short and uppercase/digit/punct
                if re.fullmatch(r'[A-Z0-9.\\-]{1,10}', s) and s not in {'—','-'}:
                    symbol=s
                    # exchange is next non-empty line
                    for k in range(j+1, min(len(lines), j+6)):
                        t=clean(lines[k])
                        if not t:
                            continue
                        if re.fullmatch(r'[A-Z0-9.\\-]{1,10}', t) and t not in {'—','-'}:
                            # another row; not exchange yet
                            continue
                        exchange=t
                        break
                    break
            if symbol:
                break
    return dict(exact=exact,state=state,ein=ein,phone=phone,addr=addr,shares=shares,symbol=symbol,exchange=exchange)


def extract_doc(path):
    lines=Path(path).read_text(errors='ignore').splitlines()
    cover=extract_cover(lines)
    # balance and income start candidates
    bal_start=find_best_heading(lines, ['balance sheets','financial position'], ['total assets'])
    inc_start=find_best_heading(lines, ['statements of operations','statements of income','statements of earnings'], ['revenue','net sales','net income','net earnings'])
    # revenue
    revenue=None
    for pat in ['total revenue','total net sales','total net revenues','net sales and revenue','net sales','net revenue','revenue','net revenues','total revenues']:
        val,idx=extract_row_value(lines, inc_start or 0, [pat])
        if val is not None:
            revenue=val; break
    # net income
    netincome=None
    for pat in ['net income (loss)','net income','net earnings (loss)','net earnings','net loss']:
        val,idx=extract_row_value(lines, inc_start or 0, [pat])
        if val is not None:
            netincome=val; break
    # total assets
    assets=None
    val,idx=extract_row_value(lines, bal_start or 0, ['total assets'])
    if val is not None:
        assets=val
    # debt
    debt=None
    for pat in ['long-term debt, less current portion','long-term debt, net of current portion','long-term debt and finance lease obligations','debt and capital lease obligations, non-current','long-term debt']:
        val,idx=extract_row_value(lines, bal_start or 0, [pat])
        if val is not None:
            debt=val; break
    if debt is None:
        # broader search for a debt note line after item 8
        val,idx=extract_row_value(lines, 0, ['long-term debt, less current portion','long-term debt, net of current portion','debt and capital lease obligations, non-current','long-term debt'])
        if val is not None:
            debt=val
    return cover, dict(revenue=revenue, netincome=netincome, assets=assets, debt=debt, bal=bal_start, inc=inc_start)

for d in obj['documents'][:8]:
    cover, fin = extract_doc(d['doc_path'])
    print('\\nDOC',d['doc_name'])
    print(cover)
    print(fin)
PY"

