import re, json
from pathlib import Path

manifest='/mnt/data/LSF/baseline_results/financebench/agentic_codex_qa_gpt54mini_all/single_cluster/all_docs/logs/all_docs.manifest.json'
obj=json.load(open(manifest))

num_re = re.compile(r'\\(?\\"'$?'"\\d[\\d,]*(?:\\.\\d+)?\\)?')
phone_re = re.compile(r'\\(?\\d{3}\\)?[\\s.-]?\\d{3}[\\s.-]?\\d{4}')
zip_re = re.compile(r'\\b\\d{5}(?:-\\d{4})?\\b')


def clean(s):
    return re.sub(r'\\s+', ' ', s).strip()

def norm(s):
    return re.sub(r'["'^a-z0-9]+'"', ' ', s.lower()).strip()

def word_count(s):
    n=norm(s)
    return len(n.split()) if n else 0

def is_phone(s):
    return bool(phone_re.search(s))

def is_numeric_only(s):
    ns=norm(s)
    return bool(ns) and re.fullmatch(r'[\\d,\\.\\-]+', ns) is not None

def is_zip_only(s):
    return bool(zip_re.fullmatch(clean(s)))

def is_label_like(s):
    c=clean(s)
    if not c:
        return False
    if c in {'"'$'"', '—', '-', '•'}:
        return False
    if is_phone(c):
        return False
    # years / numbers are not labels for our purposes
    if re.fullmatch(r'[\\d,\\.\\-/() ]+', c):
        return False
    return bool(re.search(r'[A-Za-z]', c))

def rowish_match(line, pattern):
    n=norm(line)
    p=norm(pattern)
    if p not in n:
        return False
    # avoid matching long narrative sentences for generic patterns
    if pattern == 'long-term debt' and word_count(line) > 8:
        return False
    if pattern in {'revenue','net income','net earnings','net sales','total assets'} and word_count(line) > 10:
        return False
    return True

def first_numeric_after(lines, idx, max_look=8):
    for j in range(idx+1, min(len(lines), idx+1+max_look)):
        s=clean(lines[j])
        if not s:
            continue
        # If a new label appears before a numeric value, treat this as a different row.
        if is_label_like(s):
            # allow line items like '2017' or '2022' only if we are looking at a table header? don't count them as numeric result
            return None
        m=num_re.search(s)
        if m:
            return m.group(0).replace('"'$'"','')
    return None

def find_item8(lines):
    cand=[]
    low=[norm(l) for l in lines]
    for i,l in enumerate(low):
        if 'item 8' in l:
            block=' '.join(low[i:i+4])
            if 'financial statements' in block or 'supplementary data' in block:
                cand.append(i)
    return max(cand) if cand else None

def find_best_heading_after(lines, start_idx, patterns, max_search=900):
    low=[norm(l) for l in lines]
    best=None
    best_score=(-1,-1)
    end=min(len(lines), start_idx+max_search)
    for i in range(start_idx, end):
        l=low[i]
        if not any(p in l for p in patterns):
            continue
        if 'index to' in l:
            continue
        # heading-like: not too long and contains one of the patterns on its own line
        if word_count(lines[i]) > 12:
            continue
        window=' '.join(low[i:i+90])
        score=0
        for lab in ['total assets','revenue','net sales','net income','net earnings','operating income','gross profit','cash and cash equivalents','total liabilities']:
            if lab in window:
                score += 1
        score += sum(1 for x in lines[i:i+60] if num_re.search(x))
        if (score, -i) > best_score:
            best_score=(score,-i)
            best=i
    return best

def extract_row_value(lines, start, label_patterns, max_search=220):
    low=[norm(l) for l in lines]
    end=min(len(lines), start+max_search)
    for i in range(start, end):
        s=low[i]
        if not s:
            continue
        for pat in label_patterns:
            if rowish_match(lines[i], pat):
                val=first_numeric_after(lines, i)
                if val is not None:
                    return val, i, pat
    return None, None, None

def find_line_index(lines, pred, start=0, end=None):
    end=len(lines) if end is None else min(len(lines), end)
    for i in range(start, end):
        if pred(lines[i]):
            return i
    return None

def prev_value_line(lines, idx):
    for j in range(idx-1, -1, -1):
        s=clean(lines[j])
        if not s:
            continue
        if is_label_like(s) and not is_phone(s):
            # if the value line is a label like 'One Apple Park Way' we want it; if it's a label phrase, skip it
            return s
        if is_zip_only(s) or is_phone(s) or num_re.search(s):
            return s
    return None

def extract_cover(lines):
    low=[norm(l) for l in lines]
