    if idx is not None:
        ein=prev_value_line(lines, idx)
    # phone
    phone=None
    for i in range(min(len(lines), 120)):
        m=phone_re.search(lines[i])
        if m:
            phone=m.group(0)
            break
    # address
    addr=None
    idx=find_line_index(lines, lambda s: 'address of principal executive offices' in norm(s) or 'address and telephone number' in norm(s), end=150)
    if idx is not None:
        vals=[]
        for j in range(idx-1, max(-1, idx-5), -1):
            s=clean(lines[j])
            if not s:
                continue
            if is_phone(s):
                continue
            if 'registrant' in norm(s) or 'telephone number' in norm(s):
                continue
            if 'state or other jurisdiction' in norm(s) or 'irs employer' in norm(s) or 'exact name' in norm(s):
                continue
            if is_zip_only(s) or re.search(r'[A-Za-z]', s):
                vals.append(s)
        vals=list(reversed(vals))
        # add zip if separate after address label
        for j in range(idx+1, min(len(lines), idx+5)):
            s=clean(lines[j])
            if 'zip code' in norm(s):
                z=prev_value_line(lines, j)
                if z and z not in vals:
                    vals.append(z)
                break
        addr=', '.join(vals) if vals else None
    # shares outstanding
    shares=None
    patterns=[
        r'([\\d,]+) shares of common stock were issued and outstanding',
        r'([\\d,]+) shares of common stock were outstanding',
        r'number of shares of common stock outstanding as of ["'^'"\\n]*?([\\d,]+)',
        r'as of ["'^'"\\n]*?([\\d,]+) shares of common stock',
        r'there were ([\\d,]+) shares of common stock',
        r'([\\d,]+) shares outstanding'
    ]
    text='\\n'.join(lines[:180])
    for pat in patterns:
        m=re.search(pat, text, flags=re.I)
        if m:
            shares=m.group(1)
            break
    # symbol/exchange
    symbol=None; exchange=None
    text='\\n'.join(lines[:250])
    m=re.search(r'(?i)\\b(?:traded|listed) on (["'^.'"\\n]+?) under the (?:trading|ticker) symbol\\s*[\"“]?([A-Z0-9.\\-]+)[\"”]?', text)
    if m:
        exchange=clean(m.group(1))
        symbol=m.group(2)
    if not symbol:
        m=re.search(r'(?i)\\bunder the (?:trading|ticker) symbol\\s*[\"“]?([A-Z0-9.\\-]+)[\"”]?', text)
        if m:
            symbol=m.group(1)
    if not symbol:
        # table fallback
        idx=find_line_index(lines, lambda s: 'trading symbol' in norm(s), end=200)
        if idx is not None:
            for j in range(idx+1, min(len(lines), idx+25)):
                s=clean(lines[j])
                if not s or 'title of' in norm(s) or 'name of each exchange' in norm(s):
                    continue
                if s in {'—','-'}:
                    continue
                if re.fullmatch(r'[A-Z0-9.\\-]{1,10}', s):
                    symbol=s
                    for k in range(j+1, min(len(lines), j+6)):
                        t=clean(lines[k])
                        if not t or 'securities registered' in norm(t):
                            continue
                        if re.fullmatch(r'[A-Z0-9.\\-]{1,10}', t):
                            continue
                        exchange=t
                        break
                    break
            if not exchange and symbol:
                # also look for exchange after the common stock line
                pass
    return dict(exact=exact,state=state,ein=ein,phone=phone,addr=addr,shares=shares,symbol=symbol,exchange=exchange)

def extract_doc(path):
    lines=Path(path).read_text(errors='ignore').splitlines()
    cover=extract_cover(lines)
    item8=find_item8(lines)
    if item8 is None:
        item8=0
    bal_start=find_best_heading_after(lines, item8, ['balance sheets','financial position'])
    inc_start=find_best_heading_after(lines, item8, ['statements of operations','statements of income','statements of earnings'])
    # fallback if not found
    if bal_start is None:
        bal_start=0
    if inc_start is None:
        inc_start=0
    revenue=None
    for pat in ['total net sales','total revenue','total revenues','net sales and revenue','net sales','net revenues','net revenue','revenue']:
        val,idx,used=extract_row_value(lines, inc_start, [pat])
        if val is not None:
            revenue=val; break
    netincome=None
    for pat in ['net income (loss)','net income','net earnings (loss)','net earnings','net loss']:
        val,idx,used=extract_row_value(lines, inc_start, [pat])
        if val is not None:
            netincome=val; break
    assets=None
    val,idx,used=extract_row_value(lines, bal_start, ['total assets'])
    if val is not None:
        assets=val
    debt=None
    for pat in ['long-term debt, less current portion','long-term debt, net of current portion','long-term debt and finance lease obligations','debt and capital lease obligations, non-current','adjusted carrying value of notes','total carrying value of notes','long-term debt']:
        val,idx,used=extract_row_value(lines, bal_start, [pat], max_search=600)
        if val is not None:
            debt=val; break
    if debt is None:
        # broader global fallback but with exact-ish line and short length
        for pat in ['long-term debt, less current portion','long-term debt, net of current portion','long-term debt and finance lease obligations','debt and capital lease obligations, non-current','adjusted carrying value of notes','total carrying value of notes','long-term debt']:
            val,idx,used=extract_row_value(lines, 0, [pat], max_search=len(lines))
            if val is not None:
                debt=val; break
    return cover, dict(revenue=revenue, netincome=netincome, assets=assets, debt=debt, item8=item8, bal=bal_start, inc=inc_start)

for d in obj['documents'][:12]:
    cover, fin = extract_doc(d['doc_path'])
    print('\\nDOC',d['doc_name'])
    print(cover)
    print(fin)
