import re, json
from pathlib import Path

manifest='/mnt/data/LSF/baseline_results/financebench/agentic_codex_qa_gpt54mini_all/single_cluster/all_docs/logs/all_docs.manifest.json'
obj=json.load(open(manifest))

num_re = re.compile(r'\\(?\\"'$?'"\\d[\\d,]*(?:\\.\\d+)?\\)?')
phone_re = re.compile(r'\\(?\\d{3}\\)?[\\s.-]?\\d{3}[\\s.-]?\\d{4}')
zip_re = re.compile(r'\\b\\d{5}(?:-\\d{4})?\\b')


def clean(s):
    return re.sub(r'\\s+', ' ', s).strip()

def norm(s):
    return re.sub(r'["'^a-z0-9]+'"', ' ', s.lower()).strip()

def word_count(s):
    n=norm(s)
    return len(n.split()) if n else 0

def is_phone(s):
    return bool(phone_re.search(s))

def is_zip_only(s):
    return bool(zip_re.fullmatch(clean(s)))

def is_label_like(s):
    c=clean(s)
    if not c:
        return False
    if c in {'"'$'"', '—', '-', '•'}:
        return False
    if is_phone(c):
        return False
    if re.fullmatch(r'[\\d,\\.\\-/() ]+', c):
        return False
    return bool(re.search(r'[A-Za-z]', c))

def rowish_match(line, pattern):
    n=norm(line)
    p=norm(pattern)
    if p not in n:
        return False
    if pattern == 'long-term debt' and word_count(line) > 8:
        return False
    if pattern in {'revenue','net income','net earnings','net sales','total assets'} and word_count(line) > 10:
        return False
    return True

def first_numeric_after(lines, idx, max_look=8):
    for j in range(idx+1, min(len(lines), idx+1+max_look)):
        s=clean(lines[j])
        if not s:
            continue
        if is_label_like(s):
            return None
        m=num_re.search(s)
        if m:
            return m.group(0).replace('"'$'"','')
    return None

def find_item8(lines):
    low=[norm(l) for l in lines]
    cand=[]
    for i,l in enumerate(low):
        if 'item 8' in l:
            block=' '.join(low[i:i+5])
            if 'financial statements' in block or 'supplementary data' in block:
                cand.append(i)
    if not cand:
        return None
    # Prefer the first occurrence after a reasonable threshold to skip TOC entries, but not late references.
    for threshold in [200, 300, 500, 800, 1000]:
        later=[i for i in cand if i >= threshold]
        if later:
            return min(later)
    return min(cand)

def find_best_heading_after(lines, start_idx, patterns, max_search=1200):
    low=[norm(l) for l in lines]
    best=None
    best_score=(-1, 10**9)
    end=min(len(lines), start_idx+max_search)
    for i in range(start_idx, end):
        l=low[i]
        if not any(p in l for p in patterns):
            continue
        if 'index to' in l:
            continue
        if word_count(lines[i]) > 14:
            continue
        window=' '.join(low[i:i+100])
        score=0
        for lab in ['total assets','revenue','net sales','net income','net earnings','operating income','gross profit','cash and cash equivalents','total liabilities','years ended']:
            if lab in window:
                score += 1
        score += sum(1 for x in lines[i:i+60] if num_re.search(x))
        # prefer earlier occurrence among similar scores
        key=(score, -i)
        if key > best_score:
            best_score=key
            best=i
    return best

def extract_row_value(lines, start, label_patterns, max_search=260):
    low=[norm(l) for l in lines]
    end=min(len(lines), start+max_search)
    for i in range(start, end):
        s=low[i]
        if not s:
            continue
        for pat in label_patterns:
            if rowish_match(lines[i], pat):
                val=first_numeric_after(lines, i)
                if val is not None:
                    return val, i, pat
    return None, None, None

def find_line_index(lines, patterns, start=0, end=None):
    end=len(lines) if end is None else min(len(lines), end)
    for i in range(start, end):
        n=norm(lines[i])
        if any(p in n for p in patterns):
            return i
    return None

def prev_nonempty(lines, idx):
    for j in range(idx-1, -1, -1):
        s=clean(lines[j])
        if s:
            return s
    return None

def extract_cover(lines):
    # exact name
    exact=None
    idx=find_line_index(lines, ['exact name of registrant'])
    if idx is not None:
        exact=prev_nonempty(lines, idx)
    # state / EIN
    state=None; ein=None
    idx=find_line_index(lines, ['state or other jurisdiction'])
    if idx is not None:
        state=prev_nonempty(lines, idx)
    idx=find_line_index(lines, ['irs employer identification no'])
    if idx is not None:
        ein=prev_nonempty(lines, idx)
    # phone
    phone=None
    for i in range(min(len(lines), 120)):
        m=phone_re.search(lines[i])
        if m:
            phone=m.group(0)
            break
    # address
    addr=None
    idx=find_line_index(lines, ['address of principal executive offices', 'address and telephone number'], end=150)
    if idx is not None:
        vals=[]
        for j in range(idx-1, max(-1, idx-6), -1):
            s=clean(lines[j])
            if not s:
                continue
            if is_phone(s):
                continue
            if is_label_like(s) and not is_zip_only(s):
                break
            if re.search(r'[A-Za-z]', s) or is_zip_only(s):
                vals.append(s)
        vals=list(reversed(vals))
        # append zip code if separate label follows
        zip_idx=find_line_index(lines, ['zip code'], start=idx, end=idx+10)
        if zip_idx is not None:
            z=prev_nonempty(lines, zip_idx)
            if z and z not in vals:
                vals.append(z)
        addr=', '.join(vals) if vals else None
    # shares outstanding: choose longest numeric string found near top that appears before shares wording
    shares=None
    text='\\n'.join(lines[:220])
    cands=[]
    for pat in [r'([\\d,]{3,}) shares of common stock were issued and outstanding',
                r'([\\d,]{3,}) shares of common stock were outstanding',
                r'number of shares of common stock outstanding as of ["'^'"\\n]*?([\\d,]{3,})',
                r'as of ["'^'"\\n]*?([\\d,]{3,}) shares of common stock',
                r'there were ([\\d,]{3,}) shares of common stock',
                r'([\\d,]{3,}) shares outstanding']:
        for m in re.finditer(pat, text, flags=re.I):
            cands.append(m.group(1))
    if cands:
        # normalize by removing spaces and choose longest
        cands=sorted(set(cands), key=lambda x:(len(x), x), reverse=True)
        shares=cands[0]
    # symbol/exchange
    symbol=None; exchange=None
    text='\\n'.join(lines[:300])
    for pat in [
        r'(?i)\\b(?:traded|listed) on (["'^.'"\\n]+?) under the (?:trading|ticker) symbol\\s*[\"“]?([A-Z0-9.\\-]+)[\"”\\.]?',
        r'(?i)\\bunder the (?:trading|ticker) symbol\\s*[\"“]?([A-Z0-9.\\-]+)[\"”\\.]?',
    ]:
        m=re.search(pat, text)
        if m:
            if 'under the' in pat and m.lastindex == 1:
                symbol=m.group(1).rstrip('\"”.’.,')
            else:
                exchange=clean(m.group(1)).rstrip('\"”.’.,')
                symbol=m.group(2).rstrip('\"”.’.,')
            break
    if not symbol:
        idx=find_line_index(lines, ['trading symbol', 'ticker symbol'], end=250)
        if idx is not None:
            for j in range(idx+1, min(len(lines), idx+30)):
                s=clean(lines[j])
                if not s or 'title of' in norm(s) or 'name of each exchange' in norm(s) or 'securities registered' in norm(s):
                    continue
                if s in {'—','-'}:
                    continue
                if re.fullmatch(r'[A-Z0-9.\\-]{1,12}', s):
                    symbol=s.rstrip('\"”.’.,')
                    for k in range(j+1, min(len(lines), j+8)):
                        t=clean(lines[k])
                        if not t:
                            continue
                        if 'securities registered' in norm(t) or 'title of' in norm(t) or 'name of each exchange' in norm(t):
                            continue
                        if re.fullmatch(r'[A-Z0-9.\\-]{1,12}', t):
                            continue
                        exchange=t.rstrip('\"”.’.,')
                        break
                    break
    return dict(exact=exact,state=state,ein=ein,phone=phone,addr=addr,shares=shares,symbol=symbol,exchange=exchange)

def extract_doc(path):
    lines=Path(path).read_text(errors='ignore').splitlines()
    cover=extract_cover(lines)
    item8=find_item8(lines)
    if item8 is None:
        item8=0
    bal_start=find_best_heading_after(lines, item8, ['balance sheets', 'financial position'])
    inc_start=find_best_heading_after(lines, item8, ['statements of operations', 'statements of income', 'statements of earnings'])
    if bal_start is None:
        bal_start=find_best_heading_after(lines, 0, ['balance sheets', 'financial position']) or 0
    if inc_start is None:
        inc_start=find_best_heading_after(lines, 0, ['statements of operations', 'statements of income', 'statements of earnings']) or 0
    revenue=None
    for pat in ['total net sales','total revenue','total revenues','net sales and revenue','net sales','net revenues','net revenue','revenue']:
        val,idx,used=extract_row_value(lines, inc_start, [pat])
        if val is not None:
            revenue=val; break
    netincome=None
    for pat in ['net income (loss)','net income','net earnings (loss)','net earnings','net loss']:
        val,idx,used=extract_row_value(lines, inc_start, [pat])
        if val is not None:
            netincome=val; break
    assets=None
    val,idx,used=extract_row_value(lines, bal_start, ['total assets'])
    if val is not None:
        assets=val
    debt=None
    debt_pats=['long-term debt, less current portion','long-term debt, net of current portion','long-term debt and finance lease obligations','debt and capital lease obligations, non-current','adjusted carrying value of notes','total carrying value of notes','long-term debt']
    for pat in debt_pats:
        val,idx,used=extract_row_value(lines, bal_start, [pat], max_search=800)
        if val is not None:
            debt=val; break
    if debt is None:
        for pat in debt_pats:
            val,idx,used=extract_row_value(lines, 0, [pat], max_search=len(lines))
            if val is not None:
                debt=val; break
    return cover, dict(revenue=revenue, netincome=netincome, assets=assets, debt=debt, item8=item8, bal=bal_start, inc=inc_start)

for d in obj['documents'][:20]:
    cover, fin = extract_doc(d['doc_path'])
    print('\\nDOC',d['doc_name'])
    print(cover)
    print(fin)
PY"

