import re, json
from pathlib import Path

manifest='/mnt/data/LSF/baseline_results/financebench/agentic_codex_qa_gpt54mini_all/single_cluster/all_docs/logs/all_docs.manifest.json'
obj=json.load(open(manifest))

num_re = re.compile(r'\\(?\\"'$?'"\\d[\\d,]*(?:\\.\\d+)?\\)?')
phone_re = re.compile(r'\\(?\\d{3}\\)?[\\s.-]?\\d{3}[\\s.-]?\\d{4}')
zip_re = re.compile(r'\\b\\d{5}(?:-\\d{4})?\\b')


def clean(s): return re.sub(r'\\s+',' ',s).strip()
def norm(s): return re.sub(r'["'^a-z0-9]+'"',' ',s.lower()).strip()
def word_count(s): return len(norm(s).split()) if norm(s) else 0

def is_phone(s): return bool(phone_re.search(s))
def is_zip_only(s): return bool(zip_re.fullmatch(clean(s)))
def is_meta_label(s):
    n=norm(s)
    if not n: return False
    bad=['state or other jurisdiction','incorporation or organization','irs employer','identification no','address of principal executive offices','address and telephone number','registrant s telephone number','telephone number','title of each class','name of each exchange on which registered','zip code','exact name of registrant','securities registered pursuant']
    return any(b in n for b in bad)

def rowish_match(line, pattern):
    n=norm(line); p=norm(pattern)
    if p not in n: return False
    if pattern == 'long-term debt' and word_count(line) > 8: return False
    if pattern in {'revenue','net income','net earnings','net sales','total assets'} and word_count(line) > 10: return False
    return True

def first_numeric_after(lines, idx, max_look=10):
    for j in range(idx+1, min(len(lines), idx+1+max_look)):
        s=clean(lines[j])
        if not s: continue
        if is_meta_label(s):
            return None
        m=num_re.search(s)
        if m:
            return m.group(0).replace('"'$'"','')
    return None

def find_item8(lines):
    low=[norm(l) for l in lines]
    cand=[]
    for i,l in enumerate(low):
        if 'item 8' in l:
            block=' '.join(low[i:i+5])
            if 'financial statements' in block or 'supplementary data' in block:
                cand.append(i)
    if not cand:
        return None
    # prefer later occurrences after 1000, then by shorter line length
    later=[i for i in cand if i>=1000]
    if not later:
        later=[i for i in cand if i>=200] or cand
    return min(later, key=lambda i:(word_count(lines[i]), i))

def extract_first_match(lines, start, patterns, max_search=5000):
    for i in range(start, min(len(lines), start+max_search)):
        for pat in patterns:
            if rowish_match(lines[i], pat):
                val=first_numeric_after(lines, i)
                if val is not None:
                    return val, i, pat
    return None, None, None

def extract_cover(lines):
    # state / EIN labels in cover block
    def prev_alpha(before_idx, limit=8):
        for j in range(before_idx-1, max(-1, before_idx-limit-1), -1):
            s=clean(lines[j])
            if not s or is_phone(s) or is_meta_label(s):
                continue
            if re.search(r'[A-Za-z]', s):
                return s
        return None
    def prev_ein(before_idx, limit=8):
        for j in range(before_idx-1, max(-1, before_idx-limit-1), -1):
            s=clean(lines[j])
            if not s or is_phone(s) or is_meta_label(s):
                continue
            if re.search(r'\\d', s):
                return s
        return None
    def find_idx(patterns, end=150):
        for i in range(min(end, len(lines))):
            n=norm(lines[i])
            if any(p in n for p in patterns):
                return i
        return None
    exact=None
    idx=find_idx(['exact name of registrant'])
    if idx is not None:
        exact=prev_alpha(idx)
    state=None
    idx=find_idx(['state or other jurisdiction'])
    if idx is not None:
        state=prev_alpha(idx)
    ein=None
    idx=find_idx(['irs employer identification no'])
    if idx is not None:
        ein=prev_ein(idx)
    phone=None
    for i in range(min(120, len(lines))):
        m=phone_re.search(lines[i])
        if m:
            phone=m.group(0)
            break
    addr=None
    idx=find_idx(['address of principal executive offices', 'address and telephone number'])
    if idx is not None:
        vals=[]
        for j in range(idx-1, max(-1, idx-7), -1):
            s=clean(lines[j])
            if not s or is_phone(s):
                continue
            if is_meta_label(s):
                break
            if re.search(r'[A-Za-z]', s) or is_zip_only(s):
                vals.append(s)
        vals=list(reversed(vals))
        # include zip if separately labeled after address block
        zip_idx=find_idx(['zip code'])
        if zip_idx is not None and zip_idx < idx+10:
            z=prev_ein(zip_idx)  # previous numeric line
            if z and z not in vals:
                vals.append(z)
        addr=', '.join(vals) if vals else None
    # shares
    shares=None
    for i in range(min(220, len(lines))):
        line=clean(lines[i])
        n=norm(line)
        if 'shares of common stock' not in n or 'outstanding' not in n:
            continue
        # same-line number before phrase
        m=re.search(r'([0-9][0-9,]{2,})\\s+shares of common stock', line, flags=re.I)
        if m:
            cand=m.group(1)
            shares=cand if shares is None or len(cand)>len(shares) else shares
            continue
        # next lines
        for j in range(i+1, min(len(lines), i+4)):
            s=clean(lines[j])
            if not s: continue
            if is_meta_label(s): break
            m=re.fullmatch(r'([0-9][0-9,]{2,})', s)
            if m:
                cand=m.group(1)
                shares=cand if shares is None or len(cand)>len(shares) else shares
                break
    # symbol/exchange
